class Node:
    def __init__(self, val, next = None, prev = None):
        self.val = val
        self.next = next
        self.prev = prev

class DoublyLinkList:
    def __init__(self, head = None):
        self.head = head
        self.tail = head

    def addNodeLast(self, val):
        n = Node(val)
        if not self.head:
            self.head = n
            self.tail = n
        else:
            self.tail.next = n
            self.tail.next.prev = self.tail
            self.tail = self.tail.next

    def addNodeFirst(self, val):
        n = Node(val)
        if not self.head:
            self.head = n
            self.tail = n
        else:
            n.next = self.head
            self.head.prev = n
            self.head = n

    def printLinkList(self):
        n = self.head
        while n:
            if not n.next:
                print(f"{n.val}")
            else:
                print(f"{n.val} -> ", end = "")
            n = n.next

    def printLinkListBack(self):
        n = self.tail
        while n:
            if not n.prev:
                print(f"{n.val}")
            else:
                print(f"{n.val} <- ", end = "")
            n = n.prev

if __name__ == "__main__":
    nums = [i for i in range(10)]
    ll = DoublyLinkList()
    for i in nums[:5]:
        ll.addNodeLast(i)
    ll.printLinkList()
    for i in nums[5:]:
        ll.addNodeFirst(i)
    ll.printLinkList()
    print(ll.head.val)
    ll.printLinkListBack()

import random as rand

def bubbleSort(arr):
    for i in range(len(arr)-1):
        for j in range(len(arr)-i-1):
            if arr[j] > arr[j+1]:
                arr[j], arr[j+1] = arr[j+1], arr[j]

if __name__ == "__main__":
    arr = [rand.randint(1,100) for _ in range(10)]
    print("previously: ", arr)
    bubbleSort(arr)
    print("After Sorting: ", arr)

import random as rand

def pertition(arr, l, r):
    pivot = arr[r]
    j = l-1
    for i in range(l, r):
        if arr[i] <= pivot:
            j += 1
            arr[j], arr[i] = arr[i], arr[j]

    arr[j+1], arr[r] = arr[r], arr[j+1]
    return j+1

def quickSort(arr, l, r):
    if l < r:
        pivot = pertition(arr, l, r)
        quickSort(arr, l, pivot-1)
        quickSort(arr, pivot+1, r)

if __name__ == "__main__":
    arr = [rand.randint(1,100) for _ in range(10)]
    print("previously: ", arr)
    quickSort(arr, 0, len(arr)-1)
    print("After Sorting: ", arr)

import random as rand

def selectionSort(arr):
    for i in range(len(arr)-1):
        for j in range(i+1, len(arr)):
            if arr[j] < arr[i]:
                arr[i], arr[j] = arr[j], arr[i]

if __name__ == "__main__":
    arr = [rand.randint(1,100) for _ in range(10)]
    print("previously: ", arr)
    selectionSort(arr)
    print("After Sorting: ", arr)
